  "Assembly runs shortest part first, so the head never reaches over something already placed. Heights come from the file's Height(mm) column where the library fills it in, and from the footprint name otherwise. A part with no height is placed last.": "مونتاژ از کوتاه‌ترین قطعه شروع می‌شود تا هد هرگز روی قطعهٔ جای‌گذاری‌شده نرود. ارتفاع‌ها از ستون Height(mm) فایل می‌آید، هرجا کتابخانه پر کرده باشد، وگرنه از نام فوت‌پرینت. قطعه‌ای که ارتفاع ندارد آخر جای‌گذاری می‌شود.",
