  "Changes made while the job is paused are used when you press Continuous: feeders (heights, delays, vacuum, vision type, speed, skip …) and parts (X, Y, rotation, nozzle, feeder, skip). Marks and panels are used from the next start. Adding, removing or reordering parts: stop and start again.": "تغییراتی که هنگام مکث جاب انجام شود با فشردن Continuous اعمال می‌شود: فیدرها (ارتفاع‌ها، تأخیرها، وکیوم، نوع بینایی، سرعت، پرش …) و قطعه‌ها (X، Y، چرخش، نازل، فیدر، پرش). مارک‌ها و پنل‌ها از شروع بعدی اعمال می‌شوند. افزودن، حذف یا تغییر ترتیب قطعه‌ها: توقف و شروع دوباره.",
  "Changing Wi-Fi does not touch the wired network. If the browser is connected over Wi-Fi, it loses the page while the machine moves to the new network:": "تغییر وای‌فای به شبکهٔ سیمی کاری ندارد. اگر مرورگر با وای‌فای وصل است، هنگام رفتن دستگاه به شبکهٔ جدید صفحه را از دست می‌دهد:",
