  "Check the part size after vision": "بررسی اندازهٔ قطعه پس از بینایی",
  "Checked after placing": "بررسی‌شده بعد از جای‌گذاری",
  "Choose a part, Go takes the camera to it on the left-bottom board; put the crosshair on it (arrow keys 0.1 mm, Shift 1 mm; a click on the picture moves there) and Set. Then the same part on the left-top and right-top boards (Go = where it should be).": "یک قطعه انتخاب کنید؛ Go دوربین را روی برد پایین چپ به آن می‌برد؛ ضربدر را روی آن بگذارید (کلیدهای جهت‌دار 0.1 mm، Shift 1 mm؛ کلیک روی تصویر همان‌جا می‌برد) و Set بزنید. سپس همان قطعه را روی بردهای بالا چپ و بالا راست (Go = جایی که باید باشد).",
  "Choose the part (1.) to get the nozzle, height, vision and test settings here.": "قطعه را (1.) انتخاب کنید تا تنظیمات نازل، ارتفاع، بینایی و تست اینجا بیاید.",
  "Clear": "پاک کردن",
