  "Click a feature in the image: the head moves so it is under the crosshair.": "روی یک ویژگی در تصویر کلیک کنید: هد طوری حرکت می‌کند که زیر مرکز نشانه باشد.",
  "Click a feature to bring it under the crosshair; jog with the XY pad or the keyboard.": "روی یک ویژگی کلیک کنید تا زیر ضربدر بیاید؛ با پد XY یا صفحه‌کلید حرکت دهید.",
