  "Drawing: blue = the bulk feeders now (click one to edit it), orange dashed = the matrix above before Apply, red cross = the camera.": "نقشه: آبی = فیدرهای بالک فعلی (برای ویرایش کلیک کنید)، نارنجی خط‌چین = ماتریس بالا پیش از اعمال، ضربدر قرمز = دوربین.",
  "Drives": "درایوها",
  "EMPTY: refill": "خالی: دوباره پر کنید",
  "Each camera's pixels against machine millimetres over the whole picture (scale X / Y, skew, the lens), measured with a grid of head moves; with the map on, every picture is straightened so a pixel is exactly 1 / px-per-mm everywhere. Off after a calibration: switch it on, then measure again what was measured in raw pixels (the 4-up points, the up camera's angle, the head camera offset).": "پیکسل‌های هر دوربین در برابر میلی‌متر دستگاه روی کل تصویر (مقیاس X / Y، اریبی، عدسی)، با شبکه‌ای از حرکت‌های هد اندازه‌گیری می‌شود؛ با روشن بودن نقشه، هر تصویر صاف می‌شود تا هر پیکسل همه‌جا دقیقاً 1 / px-per-mm باشد. پس از کالیبراسیون خاموش است: روشنش کنید، سپس آنچه با پیکسل خام اندازه‌گیری شده بود را دوباره اندازه بگیرید (نقاط 4-up، زاویهٔ دوربین پایین، آفست دوربین هد).",
  "Each camera's pixels against millimetres over the whole picture: scale, skew and the lens, measured and straightened.": "پیکسل‌های هر دوربین در برابر میلی‌متر روی کل تصویر: مقیاس، کجی و لنز، اندازه‌گیری و اصلاح می‌شود.",
  "Each part is picked and its leads / pads read on the bottom camera; for parts whose top shows nothing. Needs the underside taught ({0}).": "هر قطعه برداشته می‌شود و پایه‌ها / پدهایش روی دوربین پایین خوانده می‌شود؛ برای قطعه‌هایی که رویشان چیزی دیده نمی‌شود. زیر قطعه باید آموزش داده شده باشد ({0}).",
  "Each part of one board on its Gerber pads (green), with its feeder's part on top as it will be placed: the picture the bottom camera took (Take picture, or Measure from the part / Check feeders), turned by rotation − Pick angle + camera angle. Check the leads and pin 1 against the pads; change a feeder's Pick angle here and Save the job.": "هر قطعهٔ یک برد روی پدهای Gerber خودش (سبز)، با قطعهٔ فیدرش روی آن، همان‌طور که جای‌گذاری می‌شود: تصویری که دوربین پایین گرفت (عکس بگیر، یا اندازه‌گیری از قطعه / بررسی فیدرها)، چرخیده به اندازهٔ چرخش − زاویهٔ برداشتن + زاویهٔ دوربین. پایه‌ها و پین 1 را با پدها مقایسه کنید؛ زاویهٔ برداشتن یک فیدر را اینجا تغییر دهید و جاب را ذخیره کنید.",
  "Each part's pads read on the board: shifts, turns, parts that would lie across their pads, vision tips; apply what is right.": "پدهای هر قطعه روی برد خوانده می‌شود: جابه‌جایی‌ها، چرخش‌ها، قطعه‌هایی که روی پدهایشان نمی‌نشینند و نکته‌های بینایی؛ آنچه درست است را اعمال کنید.",
  "Each part's tuned settings move with its reel; each slot keeps its own position, angle and feeder / peeler power.": "تنظیمات تنظیم‌شدهٔ هر قطعه با رولش جابه‌جا می‌شود؛ هر اسلات موقعیت، زاویه و توان فیدر / پیلر خودش را نگه می‌دارد.",
