  "Feeder basic information": "اطلاعات پایهٔ فیدر",
  "Feeder by feeder the machine measures the pick point, feed rate, pick height and part size; apply what is right.": "فیدر به فیدر، دستگاه نقطهٔ برداشتن، مقدار تغذیه، ارتفاع برداشتن و اندازهٔ قطعه را اندازه می‌گیرد؛ آنچه درست است را اعمال کنید.",
  "Feeder by feeder the machine measures what you would set by hand: the pocket at the pick point (the pick point is put on it), the pitch from the pocket spacing (feed rate), the pick height by the vacuum (the nozzle goes down until it touches the part), one part picked and measured on the bottom camera (its size, a package from the library). Nothing is changed until you Apply; then Save the job.": "فیدر به فیدر، دستگاه آنچه را شما دستی تنظیم می‌کردید اندازه می‌گیرد: محفظه در نقطهٔ برداشتن (نقطهٔ برداشتن روی آن گذاشته می‌شود)، گام از فاصلهٔ محفظه‌ها (مقدار تغذیه)، ارتفاع برداشتن با وکیوم (نازل پایین می‌رود تا به قطعه برسد)، یک قطعه برداشته و روی دوربین پایین اندازه‌گیری می‌شود (اندازه‌اش، یک پکیج از کتابخانه). تا اعمال نکنید چیزی تغییر نمی‌کند؛ سپس جاب را ذخیره کنید.",
