  "Feeder {0}: its tray is used up ({1} x {2}). Refill it, then Yes (from the first cell again); No stops": "فیدر {0}: سینی‌اش تمام شد ({1} x {2}). دوباره پر کنید، سپس بله (دوباره از خانهٔ اول)؛ خیر متوقف می‌کند",
