  "Find the board's fiducials first? The head camera visits each mark (once per mounted job), so the part is shown where it really lands, board shift and turn included.": "ابتدا فیدوشیال‌های برد پیدا شود؟ دوربین هد به هر مارک سر می‌زند (یک بار برای هر جاب سوارشده)، تا قطعه همان‌جا که واقعاً می‌نشیند نشان داده شود، با احتساب جابه‌جایی و چرخش برد.",
  "Find the marks": "پیدا کردن مارک‌ها",
  "Find the marks first when the board has them (then the parts are corrected against the marks); without marks the parts are taken through panel 1. Go = the camera to where the part should be; put the crosshair on its real centre; Set. Any part can be used: type its name in Part, or put the crosshair on a part you see and ask which part is under it. Or a board point: + board point, type its X, Y on the board. ◎ Set = centre on the round mark, then set.": "اگر برد مارک دارد، اول مارک‌ها را پیدا کنید (سپس قطعه‌ها بر اساس مارک‌ها اصلاح می‌شوند)؛ بدون مارک، قطعه‌ها از روی پنل 1 گرفته می‌شوند. Go = دوربین به جایی که قطعه باید باشد؛ ضربدر را روی مرکز واقعی آن بگذارید؛ Set. هر قطعه‌ای قابل استفاده است: نامش را در Part بنویسید، یا ضربدر را روی قطعه‌ای که می‌بینید بگذارید و بپرسید کدام قطعه زیر آن است. یا یک نقطهٔ برد: + نقطهٔ برد، X و Y آن را روی برد بنویسید. ◎ Set = مرکز روی مارک گرد، سپس تنظیم.",
  "Find the part centre: the pads under the camera are found and boxed; the box centre is recorded.": "مرکز قطعه را پیدا کن: پدهای زیر دوربین پیدا و قاب‌بندی می‌شوند؛ مرکز قاب ثبت می‌شود.",
  "Finds the job's fiducials. With 3 or more marks the residuals should be a few hundredths of a mm.": "فیدوشیال‌های جاب را پیدا می‌کند. با 3 مارک یا بیشتر، باقی‌مانده‌ها باید چند صدم mm باشند.",
  "First bring the head camera near a round mark on the board (a fiducial; Manual → Centre on the circle): the mark is followed over a 7 x 7 grid of ±3.2 mm.": "اول دوربین هد را نزدیک یک مارک گرد روی برد ببرید (فیدوشیال؛ Manual → Centre on the circle): مارک روی شبکهٔ 7 x 7 با ±3.2 mm دنبال می‌شود.",
  "Fit           all three points (best fit, average error {0}mm)": "برازش         هر سه نقطه (بهترین برازش، میانگین خطا {0}mm)",
  "Fit View": "جا دادن در نما",
  "Fit of {0} points (nominal → measured)": "برازش {0} نقطه (اسمی → اندازه‌گیری‌شده)",
