  "Footprints": "فوت‌پرینت‌ها",
  "Footprints that say more than a size (LEDs, tantalums, ICs) were left as they are.": "فوت‌پرینت‌هایی که بیش از اندازه اطلاعات دارند (LED، تانتالیوم، IC) دست‌نخورده ماندند.",
  "For parts whose leads matter more than their body (SOT-23, SOIC, QFP, connectors). Test it on the Pad alignment page, step 6.": "برای قطعاتی که پایه‌هایشان مهم‌تر از بدنه است (SOT-23، SOIC، QFP، کانکتورها). در صفحهٔ تراز پد، گام 6 آزمایش کنید.",
