  "Lay the feeders out again by the rules?\n\n  - fiducial on feeder 49, placement skipped\n  - busiest 8mm parts in the middle of 1-17: 7, 8, 6, 9, 5, 10 ...\n  - 8mm feeders: nozzles 1 and 3, feed rhythm 4\n  - big feeders (M7, SO-16, 1210 ...) from 20 up\n\nPlacement order and coordinates stay as they are.": "فیدرها دوباره طبق قوانین چیده شوند؟\n\n  - فیدوشیال روی فیدر 49، جای‌گذاری رد می‌شود\n  - پرکاربردترین قطعات 8mm وسط 1-17: 7، 8، 6، 9، 5، 10 ...\n  - فیدرهای 8mm: نازل‌های 1 و 3، ریتم تغذیه 4\n  - فیدرهای بزرگ (M7، SO-16، 1210 ...) از 20 به بعد\n\nترتیب جای‌گذاری و مختصات همان می‌ماند.",
