  "Suggested": "پیشنهادی",
  "Suggestions": "پیشنهادها",
  "Suggests which slot each reel goes in and re-orders the placements for the least head travel, keeping shortest parts first. Travel is measured as the longer of the X and Y moves, since a gantry drives both at once.": "پیشنهاد می‌دهد هر رول در کدام استک برود و جای‌گذاری‌ها را برای کمترین حرکت هد دوباره مرتب می‌کند، با حفظ اولویت قطعات کوتاه. حرکت برابر بزرگ‌ترین مقدار از حرکت X و Y حساب می‌شود، چون گنتری هر دو را هم‌زمان می‌راند.",
