  "Try pad alignment and lead vision live on a test board, step by step, and save the values that work.": "آزمایش تراز پد و بینایی پایه‌ها به‌صورت زنده روی یک برد تست، گام‌به‌گام، و ذخیرهٔ مقادیر درست.",
  "Turn": "چرخش",
