  "Turn the board {0}{1}° (counter-clockwise +) about its zero point {2}, {3}? Parts and marks turn; the panels stay where they are.": "برد را {0}{1}° (پادساعت‌گرد +) حول نقطهٔ صفرش {2}، {3} بچرخانم؟ قطعه‌ها و مارک‌ها می‌چرخند؛ پنل‌ها سر جایشان می‌مانند.",
  "Turn the selected part 180°.": "قطعهٔ انتخاب‌شده را 180° بچرخانید.",
  "Turn the selected part 90° clockwise.": "قطعهٔ انتخاب‌شده را 90° ساعتگرد بچرخانید.",
  "Turn the selected part 90° counter-clockwise.": "قطعهٔ انتخاب‌شده را 90° پادساعتگرد بچرخانید.",
  "Turn the selected part to the angle typed.": "قطعهٔ انتخاب‌شده را به زاویهٔ واردشده بچرخان.",
  "Turn the whole board 180° about its centre. Fiducials stay where they are.": "کل برد را 180° حول مرکزش بچرخانید. فیدوشیال‌ها سر جایشان می‌مانند.",
  "Turn the whole board 90° clockwise about its centre. Fiducials stay where they are.": "کل برد را 90° ساعتگرد حول مرکزش بچرخانید. فیدوشیال‌ها سر جایشان می‌مانند.",
  "Turn the whole board 90° counter-clockwise about its centre. Fiducials stay where they are.": "کل برد را 90° پادساعتگرد حول مرکزش بچرخانید. فیدوشیال‌ها سر جایشان می‌مانند.",
  "Type": "نوع",
