  "Update": "به‌روزرسانی",
  "Updates": "به‌روزرسانی‌ها",
  "Uploads and outputs go to {0}; NeoDen job files are in {1}.": "آپلودها و خروجی‌ها در {0} می‌روند؛ فایل‌های جاب NeoDen در {1} هستند.",
  "Upload…": "آپلود…",
  "Upper-right X / Y": "بالا‌راست X / Y",
  "Uptime": "مدت روشن بودن",
  "Use Footprint Height": "استفاده از ارتفاع فوت‌پرینت",
