  "Use lead vision": "استفاده از بینایی پایه‌ها",
  "Use pad alignment": "استفاده از تراز پد",
  "Use the slots that look untaught": "استفاده از اسلات‌هایی که آموزش‌ندیده به نظر می‌رسند",
  "Use the suggested ({0})": "استفاده از پیشنهادی ({0})",
  "Use this height for every part with this package.": "این ارتفاع را برای همهٔ قطعات با این پکیج به کار ببر.",
  "Uses the loaded machine file as the template.": "فایل دستگاه بارگذاری‌شده را به‌عنوان الگو استفاده می‌کند.",
  "Using the loaded machine file as a template: taught feeder positions, board/mark/mirror rows and every column this dialog does not set are kept.": "فایل دستگاه بارگذاری‌شده به‌عنوان قالب استفاده می‌شود: موقعیت‌های آموزش‌دیدهٔ فیدر، ردیف‌های برد/مارک/آینه و هر ستونی که این پنجره تنظیم نمی‌کند حفظ می‌شود.",
