  "WARNING: default password or update key in {0}; change them": "هشدار: گذرواژهٔ پیش‌فرض یا کلید به‌روزرسانی در {0}؛ آن‌ها را عوض کنید",
  "WARNING: neither way puts C within {0}mm -- one of the three was sighted on the wrong part.": "هشدار: در هیچ‌کدام از دو حالت C در {0}mm قرار نمی‌گیرد -- یکی از سه نقطه روی قطعهٔ اشتباه نشانه‌روی شده است.",
