  "the head camera over that cell": "دوربین هد روی آن خانه",
  "the head camera over the pick point": "دوربین هد روی نقطهٔ برداشتن",
  "the head camera over the point where this part lands (through the board marks)": "دوربین هد روی نقطه‌ای که این قطعه می‌نشیند (از طریق مارک‌های برد)",
