  "the job is set to Test run (no parts placed): this one part is placed for real, with its feeder's vision": "جاب روی اجرای آزمایشی است (قطعه‌ای گذاشته نمی‌شود): این یک قطعه واقعاً با بینایی فیدرش گذاشته می‌شود",
  "the job was changed since it stopped (parts or panels): it cannot go on where it stopped; start a new board, or undo the change": "جاب از زمان توقف تغییر کرده است (قطعه‌ها یا پنل‌ها): نمی‌تواند از جای توقف ادامه دهد؛ برد جدید شروع کنید یا تغییر را برگردانید",
  "the last 30 days": "30 روز گذشته",
  "the last 7 days": "7 روز گذشته",
