  "the last year": "یک سال گذشته",
  "the list of parts changed (added, removed or moved): part edits are not taken mid-job; stop and start again": "فهرست قطعه‌ها تغییر کرده است (اضافه، حذف یا جابه‌جا شده): ویرایش قطعه‌ها وسط جاب اعمال نمی‌شود؛ متوقف کنید و دوباره شروع کنید",
  "the machine screen": "صفحهٔ دستگاه",
  "the map: rms {0} px, max {1} px ({2} mm) · one matrix would leave max {3} px ({4} mm)": "نقشه: rms {0} px، بیشینه {1} px ({2} mm) · یک ماتریس بیشینه {3} px ({4} mm) باقی می‌گذاشت",
