  "the nozzle did not get the part at {0} mm (check the pick height)": "نازل در {0} mm قطعه را برنداشت (ارتفاع برداشت را بررسی کنید)",
  "the nozzle did not meet the part (no pressure drop down to 13 mm)": "نازل به قطعه نرسید (تا 13 mm افت فشاری نبود)",
  "the nozzle goes down on the pick point with the suction on until it touches the part (the pressure falls): Pick height from that": "نازل با مکش روشن روی نقطهٔ برداشتن پایین می‌رود تا به قطعه برسد (فشار افت می‌کند): ارتفاع برداشتن از همین به دست می‌آید",
  "the other kinds go to their other feeder, else to no feeder": "انواع دیگر به فیدر دیگرشان می‌روند، وگرنه به هیچ فیدری",
  "the part is picked, its underside photographed on the bottom camera, then put back …": "قطعه برداشته می‌شود، زیر آن با دوربین پایین عکس گرفته می‌شود، سپس برمی‌گردد …",
  "the part is {0} x {1} mm, the feeder's part {2} x {3} ({4}): a wrong reel? Load the right one, or take this size": "قطعه {0} x {1} mm است، قطعهٔ فیدر {2} x {3} ({4}): رول اشتباه است؟ رول درست را بگذارید یا این اندازه را بپذیرید",
  "the parts come loose from that container: found and checked by the cameras, picked by the vacuum; Pick angle = how the taught part lay against the footprint": "قطعه‌ها از آن ظرف آزاد می‌شوند: با دوربین‌ها پیدا و بررسی می‌شوند، با وکیوم برداشته می‌شوند؛ زاویهٔ برداشتن = نحوهٔ قرار گرفتن قطعهٔ آموزش‌داده‌شده نسبت به فوت‌پرینت",
  "the parts nearest to the camera now: pick the one under the crosshair and set it": "نزدیک‌ترین قطعات به دوربین: قطعهٔ زیر ضربدر را انتخاب و تنظیم کنید",
  "the pick height by the vacuum": "ارتفاع برداشتن با وکیوم",
  "the pitch → the feed rate": "گام → نرخ تغذیه",
