  "the pocket at the pick point is empty: feed the tape on (Feed test)": "جیبِ نقطهٔ برداشت خالی است: نوار را جلو ببرید (تست تغذیه)",
  "the pocket is {0} mm from the pick point: set the pick point on it": "جیب {0} mm از نقطهٔ برداشت فاصله دارد: نقطهٔ برداشت را روی آن بگذارید",
  "the pocket → the pick point": "پاکت → نقطهٔ برداشتن",
  "the pressure never fell down to 13 mm (the lowest the nozzle goes): no part at the pick point, or the nozzle leaks": "فشار تا 13 mm (پایین‌ترین حد نازل) هرگز نیفتاد: قطعه‌ای در نقطهٔ برداشت نیست یا نازل نشتی دارد",
  "the same corner on the right-most block of the first row: the step in X": "همان گوشه روی راست‌ترین بلوک ردیف اول: گام در X",
