  "vision 4-up: the nozzles' middle is {0}, {1} mm from the image centre (posCamLookUpMouseMouseCenter)": "بینایی 4-up: وسط نازل‌ها {0}، {1} mm از مرکز تصویر فاصله دارد (posCamLookUpMouseMouseCenter)",
